def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([1, 2]), fmt([7, 7, 7, 7]), fmt([1, 5, 2, 8, 3]), fmt([3, 6, 9, 12]), fmt([9, 4, 7, 2, 10]), fmt([20, 1, 15, 3, 10, 5, 8]), fmt([-1000000000, 0, 1000000000])]
    for n in (2, 3, 5, 7, 9, 11, 13):
        for _ in range(3):
            hi = rng.choice([2, 6, 15, 1000])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    n = 1000
    M = 10**9
    tests.append(fmt([rng.randint(-M, M) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 40) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 500) for _ in range(n)]))
    tests.append(fmt([i * 1000000 - 500000000 if rng.random() < 0.6 else rng.randint(-M, M) for i in range(n)]))
    return tests

